use mtime_core::{CoordinateTime,Tcb,Tcg,Tdb,TemporalError,Tt,SECONDS_PER_DAY};

pub const LG:f64=6.969_290_134e-10;pub const LB:f64=1.550_519_768e-8;pub const TDB0_SECONDS:f64=-6.55e-5;pub const JD_MJD0:f64=2_400_000.5;pub const MJD_1977:f64=43_144.0;pub const TT_MINUS_TAI_SECONDS:f64=32.184;pub const J2000_UTC_UNIX_SECONDS:f64=946_727_935.816;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum DtrQuality{Reference,ApproximateGeocentric}
#[derive(Debug,Clone,Copy,PartialEq)]pub struct DtrValue{pub seconds:f64,pub uncertainty_seconds:f64,pub quality:DtrQuality,pub source:&'static str}
pub trait DtrProvider{fn dtr(&self,tt:&CoordinateTime<Tt>)->Result<DtrValue,TemporalError>;}
#[derive(Debug,Clone,Copy,Default)]pub struct NasaSimpleDtr;
impl DtrProvider for NasaSimpleDtr{fn dtr(&self,tt:&CoordinateTime<Tt>)->Result<DtrValue,TemporalError>{let g=(357.53+0.985_600_3*(tt.jd()-2_451_545.0)).to_radians();Ok(DtrValue{seconds:0.001_658*g.sin()+0.000_014*(2.0*g).sin(),uncertainty_seconds:0.000_1,quality:DtrQuality::ApproximateGeocentric,source:"NASA/TP-2022-0014814 compact TDB-TT approximation"})}}

pub fn tt_to_tcg(tt:&CoordinateTime<Tt>)->Result<CoordinateTime<Tcg>,TemporalError>{let p=tt.jd_parts();let t77t=MJD_1977+TT_MINUS_TAI_SECONDS/SECONDS_PER_DAY;let rate=LG/(1.0-LG);let(d1,d2)=if p.d1.abs()>p.d2.abs(){(p.d1,p.d2+((p.d1-JD_MJD0)+(p.d2-t77t))*rate)}else{(p.d1+((p.d2-JD_MJD0)+(p.d1-t77t))*rate,p.d2)};CoordinateTime::<Tcg>::new(d1,d2,tt.uncertainty_seconds())}
pub fn tcg_to_tt(tcg:&CoordinateTime<Tcg>)->Result<CoordinateTime<Tt>,TemporalError>{let p=tcg.jd_parts();let t77t=MJD_1977+TT_MINUS_TAI_SECONDS/SECONDS_PER_DAY;let(d1,d2)=if p.d1.abs()>p.d2.abs(){(p.d1,p.d2-((p.d1-JD_MJD0)+(p.d2-t77t))*LG)}else{(p.d1-((p.d2-JD_MJD0)+(p.d1-t77t))*LG,p.d2)};CoordinateTime::<Tt>::new(d1,d2,tcg.uncertainty_seconds())}
pub fn tcb_to_tdb(tcb:&CoordinateTime<Tcb>)->Result<CoordinateTime<Tdb>,TemporalError>{let p=tcb.jd_parts();let t77td=JD_MJD0+MJD_1977;let t77tf=TT_MINUS_TAI_SECONDS/SECONDS_PER_DAY;let tdb0=TDB0_SECONDS/SECONDS_PER_DAY;let(d1,d2)=if p.d1.abs()>p.d2.abs(){let d=p.d1-t77td;(p.d1,p.d2+tdb0-(d+(p.d2-t77tf))*LB)}else{let d=p.d2-t77td;(p.d1+tdb0-(d+(p.d1-t77tf))*LB,p.d2)};CoordinateTime::<Tdb>::new(d1,d2,tcb.uncertainty_seconds())}
pub fn tdb_to_tcb(tdb:&CoordinateTime<Tdb>)->Result<CoordinateTime<Tcb>,TemporalError>{let p=tdb.jd_parts();let t77td=JD_MJD0+MJD_1977;let t77tf=TT_MINUS_TAI_SECONDS/SECONDS_PER_DAY;let tdb0=TDB0_SECONDS/SECONDS_PER_DAY;let rate=LB/(1.0-LB);let(d1,d2)=if p.d1.abs()>p.d2.abs(){let d=t77td-p.d1;let f=p.d2-tdb0;(p.d1,f-(d-(f-t77tf))*rate)}else{let d=t77td-p.d2;let f=p.d1-tdb0;(f-(d-(f-t77tf))*rate,p.d2)};CoordinateTime::<Tcb>::new(d1,d2,tdb.uncertainty_seconds())}
pub fn tt_to_tdb(tt:&CoordinateTime<Tt>,dtr:DtrValue)->Result<CoordinateTime<Tdb>,TemporalError>{if !dtr.seconds.is_finite()||!dtr.uncertainty_seconds.is_finite(){return Err(TemporalError::NonFinite);}let p=tt.jd_parts();let delta=dtr.seconds/SECONDS_PER_DAY;let(d1,d2)=if p.d1.abs()>p.d2.abs(){(p.d1,p.d2+delta)}else{(p.d1+delta,p.d2)};CoordinateTime::<Tdb>::new(d1,d2,tt.uncertainty_seconds().hypot(dtr.uncertainty_seconds))}

#[derive(Debug,Clone,Copy)]pub struct UtcInstant{pub unix_seconds:i64,pub nanoseconds:u32}
#[derive(Debug,Clone,Copy)]struct LeapEntry{unix_effective:i64,tai_minus_utc:i64}
const LEAPS:&[LeapEntry]=&[
LeapEntry{unix_effective:63_072_000,tai_minus_utc:10},LeapEntry{unix_effective:78_796_800,tai_minus_utc:11},LeapEntry{unix_effective:94_694_400,tai_minus_utc:12},LeapEntry{unix_effective:126_230_400,tai_minus_utc:13},LeapEntry{unix_effective:157_766_400,tai_minus_utc:14},LeapEntry{unix_effective:189_302_400,tai_minus_utc:15},LeapEntry{unix_effective:220_924_800,tai_minus_utc:16},LeapEntry{unix_effective:252_460_800,tai_minus_utc:17},LeapEntry{unix_effective:283_996_800,tai_minus_utc:18},LeapEntry{unix_effective:315_532_800,tai_minus_utc:19},LeapEntry{unix_effective:362_793_600,tai_minus_utc:20},LeapEntry{unix_effective:394_329_600,tai_minus_utc:21},LeapEntry{unix_effective:425_865_600,tai_minus_utc:22},LeapEntry{unix_effective:489_024_000,tai_minus_utc:23},LeapEntry{unix_effective:567_993_600,tai_minus_utc:24},LeapEntry{unix_effective:631_152_000,tai_minus_utc:25},LeapEntry{unix_effective:662_688_000,tai_minus_utc:26},LeapEntry{unix_effective:709_948_800,tai_minus_utc:27},LeapEntry{unix_effective:741_484_800,tai_minus_utc:28},LeapEntry{unix_effective:773_020_800,tai_minus_utc:29},LeapEntry{unix_effective:820_454_400,tai_minus_utc:30},LeapEntry{unix_effective:867_715_200,tai_minus_utc:31},LeapEntry{unix_effective:915_148_800,tai_minus_utc:32},LeapEntry{unix_effective:1_136_073_600,tai_minus_utc:33},LeapEntry{unix_effective:1_230_768_000,tai_minus_utc:34},LeapEntry{unix_effective:1_341_100_800,tai_minus_utc:35},LeapEntry{unix_effective:1_435_708_800,tai_minus_utc:36},LeapEntry{unix_effective:1_483_228_800,tai_minus_utc:37}];
pub fn tai_minus_utc(utc:UtcInstant)->Result<i64,TemporalError>{if utc.unix_seconds<LEAPS[0].unix_effective{return Err(TemporalError::OutsideSupportedRange);}Ok(LEAPS.iter().rev().find(|x|utc.unix_seconds>=x.unix_effective).map_or(10,|x|x.tai_minus_utc))}
pub fn utc_to_tt(utc:UtcInstant)->Result<CoordinateTime<Tt>,TemporalError>{let offset=tai_minus_utc(utc)? as f64+TT_MINUS_TAI_SECONDS;let utc_s=utc.unix_seconds as f64+f64::from(utc.nanoseconds)/1e9;let tt_unix_like=utc_s+offset;let j2000=J2000_UTC_UNIX_SECONDS+32.0+TT_MINUS_TAI_SECONDS;CoordinateTime::<Tt>::new(2_451_545.0,(tt_unix_like-j2000)/SECONDS_PER_DAY,1e-9)}

#[cfg(test)]mod tests{use super::*;#[test]fn sofa_tt_to_tcg(){let tt=CoordinateTime::<Tt>::new(2_453_750.5,0.892_482_639,0.0).unwrap();assert!((tt_to_tcg(&tt).unwrap().jd_parts().d2-0.892_490_031_250_858_7).abs()<=1e-12);}#[test]fn sofa_tcb_to_tdb(){let tcb=CoordinateTime::<Tcb>::new(2_453_750.5,0.893_019_599,0.0).unwrap();assert!((tcb_to_tdb(&tcb).unwrap().jd_parts().d2-0.892_855_136_274_634_4).abs()<=1e-12);}#[test]fn j2000_utc_maps_to_j2000_tt(){let tt=utc_to_tt(UtcInstant{unix_seconds:946_727_935,nanoseconds:816_000_000}).unwrap();assert!((tt.jd()-2_451_545.0).abs()<1e-12);}#[test]fn dtr_is_millisecond_scale(){let tt=CoordinateTime::<Tt>::new(2_451_545.0,0.0,0.0).unwrap();let d=NasaSimpleDtr.dtr(&tt).unwrap();assert!(d.seconds.abs()<0.002);}}
